        "role": "assistant",
        "tool_calls": null,
        "content": "```python\nresponse = client.chat.complete(\nmodel=\"open-mistral-nemo\",\nmessages=[\n{\"role\": \"user\", \"content\": \"Summarize this document.\"}\n]\n)\n```"
      }
